import json

task_id = "task-8625f9bc"
filepath = f"/home/USER/runs/paper/qwen-in-glm-hpl-u1-letter/frozen/seen-2/play/users/u077/system/state/workspace/programs/{task_id}.json"
with open(filepath, 'r') as f:
    pairs = json.load(f)

def transform(grid):
    """
    For each color (except background):
    - In each row: fill background cells between the minimum and maximum column
                      of ALL cells of that color (within the grid width)
    - In each column: fill background cells between the minimum and maximum row
                      of ALL cells of that color (within the grid height)
    """
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Get background color (most common)
    from collections import Counter
    all_cells = [cell for row in grid for cell in row]
    bg = Counter(all_cells).most_common(1)[0][0]

    result = [r[:] for r in grid]

    # Step 1: Row fills - for each color, fill between min and max col
    for r in range(rows):
        color_ranges = {}
        for c in range(cols):
            color = grid[r][c]
            if color != bg:
                if color not in color_ranges:
                    color_ranges[color] = [c, c]
                else:
                    color_ranges[color] = [min(color_ranges[color][0], c), max(color_ranges[color][1], c)]

        for color, (start_col, end_col) in color_ranges.items():
            for c in range(start_col, end_col + 1):
                if grid[r][c] == bg:
                    result[r][c] = 2

    # Step 2: Column fills - for each color, fill between min and max row
    for c in range(cols):
        color_ranges = {}
        for r in range(rows):
            color = result[r][c]  # Use RESULT after row fills
            if color != bg:
                if color not in color_ranges:
                    color_ranges[color] = [r, r]
                else:
                    color_ranges[color] = [min(color_ranges[color][0], r), max(color_ranges[color][1], r)]

        for color, (start_row, end_row) in color_ranges.items():
            for r in range(start_row, end_row + 1):
                if result[r][c] == bg:
                    result[r][c] = 2

    return result

# Test
print("Testing all pairs:")
for idx in range(4):
    pair = pairs[idx]
    inp = pair['input']
    out = pair['output']
    h, w = len(inp), len(inp[0])

    result = transform(inp)
    match = result == [row[:] for row in out]
    status = "✓ MATCH" if match else "✗ MISMATCH"
    print(f"Pair {idx}: {status}")
    if not match:
        print(f"  Expected max diff: {max([(abs(inp[i][j] - out[i][j]) if inp[i][j] != out[i][j] else 0 for i in range(h) for j in range(w))])}")

