def transform(grid):
    from collections import Counter
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    all_cells = [cell for row in grid for cell in row]
    bg = Counter(all_cells).most_common(1)[0][0]

    result = [r[:] for r in grid]
    FILL_VALUE = 2

    # PROCESS ROWS: fill gaps where adjacent segments have different sizes
    for r in range(rows):
        all_active = [c for c in range(cols) if grid[r][c] != bg]
        if len(all_active) >= 2:
            segments = []
            current_seg = [all_active[0]]
            for i in range(1, len(all_active)):
                c = all_active[i]
                prev_c = all_active[i-1]
                if c == prev_c + 1 and grid[r][c] == grid[r][prev_c]:
                    current_seg.append(c)
                else:
                    segments.append(current_seg)
                    current_seg = [c]
            segments.append(current_seg)

            for i in range(len(segments) - 1):
                size1 = len(segments[i])
                size2 = len(segments[i + 1])
                gap_start = segments[i][-1] + 1
                gap_end = segments[i + 1][0] - 1
                if size1 != size2:
                    for c in range(gap_start, gap_end + 1):
                        if result[r][c] == bg:
                            result[r][c] = FILL_VALUE

    # PROCESS COLUMNS: same rule
    for c in range(cols):
        all_active = [r for r in range(rows) if grid[r][c] != bg]
        if len(all_active) >= 2:
            segments = []
            current_seg = [all_active[0]]
            for i in range(1, len(all_active)):
                r = all_active[i]
                prev_r = all_active[i-1]
                if r == prev_r + 1 and grid[r][c] == grid[prev_r][c]:
                    current_seg.append(r)
                else:
                    segments.append(current_seg)
                    current_seg = [r]
            segments.append(current_seg)

            for i in range(len(segments) - 1):
                size1 = len(segments[i])
                size2 = len(segments[i + 1])
                gap_start = segments[i][-1] + 1
                gap_end = segments[i + 1][0] - 1
                if size1 != size2:
                    for r in range(gap_start, gap_end + 1):
                        if result[r][c] == bg:
                            result[r][c] = FILL_VALUE

    return result

